class ValidationError extends Error {
  constructor(field, message) {
    super(message);
    this.name = "ValidationError";
    this.field = field;
  }
}

function parseAmount(text) {
  const dollars = Number(text);
  if (text.trim() === "" || !Number.isFinite(dollars) || dollars <= 0) {
    throw new ValidationError("amount", "Enter an amount greater than zero.");
  }
  return Math.round(dollars * 100);
}

function tryAdd(list, label, amountText) {
  try {
    if (label.trim() === "") {
      throw new ValidationError("label", "Enter what you spent money on.");
    }
    const expense = { label: label.trim(), amount: parseAmount(amountText) };
    return { ok: true, list: [...list, expense] };
  } catch (error) {
    if (error instanceof ValidationError) {
      return { ok: false, field: error.field, message: error.message };
    }
    throw error;
  }
}

console.log(tryAdd([], "Tea", "abc"));

